    this.connectionPool = new ConnectionPool()
    this.types = crateTypes
  }

  connect (host, port) {
    if (port && port >= 0) {
      this.connectionPool.connect(`http://${host}:${port}`)
    } else {
      this.connectionPool.connect(host)
    }
  }

  /**
   * @param {string} tableName
   * @param {string[]} options
   */
  insert (tableName, options) {
    if (arguments.length < 2) {
      return Promise.reject(new Error('missed arguments!'))
    }

    if (!tableName) {
      return Promise.reject(new Error('Table name is not specified'))
    }

    if (!options) {
      return Promise.reject(new Error('Record entry is not defined'))
    }

    const preparedOptions = _prepareOptions(options)
    const preparedQuery = `INSERT INTO ${tableName} (${preparedOptions.keys}) VALUES (${preparedOptions.values})`

    return this._executeSql(preparedQuery, preparedOptions.args)
  }

